bands = [('2.4 GHz', -62, 14), ('5.8 GHz', -71, 6), ('900 MHz', -84, 2)]
for band, strength, seconds in bands:
    if seconds >= 10 and strength > -70:
        cls = 'control-like pattern'
    elif seconds >= 5:
        cls = 'video-like wide pattern'
    else:
        cls = 'brief unclassified burst'
    print(band + ': ' + str(strength) + ' dBm, ' + str(seconds) + 's -> ' + cls)
