packets = [('ID-7A3Q', 'complete'), ('ID-9B1X', 'incomplete'), ('ID-7A3Q', 'complete')]
seen = {}
for bid, status in packets:
    if status == 'complete':
        seen[bid] = seen.get(bid, 0) + 1
        print(bid + ': complete packet logged')
    else:
        print(bid + ': incomplete packet, stored as incomplete')
print('Remote-ID Reader: ' + str(len(seen)) + ' distinct complete broadcast(s) logged')

def inside(x, y):
    return 0 <= x <= 10 and 0 <= y <= 10
